using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Aspire.Hosting.Testing;

namespace MyApp.Evals;

[TestClass]
public class ChatEvals
{
    private static DistributedApplicationFactory? _appFactory;
    private static IChatClient? _chatClient;
    private static ChatConfiguration? _chatConfig;

    [ClassInitialize]
    public static async Task Setup(TestContext context)
    {
        _appFactory = new DistributedApplicationFactory(typeof(Program));
        await _appFactory.StartAsync();

        var connectionString = await _appFactory.GetConnectionString("chat");
        Assert.IsNotNull(connectionString, "The 'chat' resource connection string should be available.");

        _chatClient = new Azure.AI.OpenAI.AzureOpenAIClient(
            new Uri(connectionString))
            .GetChatClient("gpt-4o-mini")
            .AsIChatClient();

        _chatConfig = new ChatConfiguration(_chatClient);
    }

    [ClassCleanup]
    public static async Task Cleanup()
    {
        if (_appFactory is not null)
            await _appFactory.DisposeAsync();
    }

    [TestMethod]
    public async Task Chat_Response_Is_Relevant()
    {
        var evaluator = new RelevanceEvaluator();

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France?")
        };

        var response = await _chatClient!.GetResponseAsync(messages);

        var results = await evaluator.EvaluateAsync(messages, response, _chatConfig!);

        foreach (var metric in results)
        {
            AssertMetricPass(metric);
        }
    }

    [TestMethod]
    public async Task Chat_Response_Is_Coherent()
    {
        var evaluator = new CoherenceEvaluator();

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Explain photosynthesis in two sentences.")
        };

        var response = await _chatClient!.GetResponseAsync(messages);

        var results = await evaluator.EvaluateAsync(messages, response, _chatConfig!);

        foreach (var metric in results)
        {
            AssertMetricPass(metric);
        }
    }

    [TestMethod]
    public async Task Chat_Response_Is_Fluent()
    {
        var evaluator = new FluencyEvaluator();

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Write a brief summary of how computers work.")
        };

        var response = await _chatClient!.GetResponseAsync(messages);

        var results = await evaluator.EvaluateAsync(messages, response, _chatConfig!);

        foreach (var metric in results)
        {
            AssertMetricPass(metric);
        }
    }

    private static void AssertMetricPass(EvaluationMetric metric)
    {
        var interpretation = metric.Interpretation;
        if (interpretation is not null)
        {
            Assert.AreNotEqual(EvaluationRating.Unacceptable, interpretation.Rating,
                $"Metric '{metric.Name}' was rated Unacceptable. Reason: {metric.Reason}");
            Assert.AreNotEqual(EvaluationRating.Poor, interpretation.Rating,
                $"Metric '{metric.Name}' was rated Poor. Reason: {metric.Reason}");
        }
    }
}

